from fastapi import FastAPI, Response, HTTPException
from fastapi.responses import HTMLResponse, StreamingResponse
import requests
import os

app = FastAPI(title="Meta Agent V1", version="1.0.0")

HTML_CONTENT = """
<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Meta Agent V1</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #0f172a; color: #f8fafc; margin: 0; padding: 40px; display: flex; flex-direction: column; align-items: center; }
        .container { max-width: 600px; width: 100%; background: #1e293b; padding: 30px; border-radius: 12px; box-shadow: 0 10px 25px rgba(0,0,0,0.3); }
        h1 { color: #38bdf8; text-align: center; margin-bottom: 25px; }
        .status { background: #0284c7; color: white; padding: 10px; border-radius: 6px; text-align: center; font-weight: bold; margin-bottom: 25px; }
        .section { margin-bottom: 25px; }
        label { display: block; margin-bottom: 8px; font-weight: 600; }
        input[type="text"] { width: 100%; padding: 12px; border: 1px solid #475569; background: #0f172a; color: white; border-radius: 6px; box-sizing: border-box; margin-bottom: 10px; }
        button { width: 100%; padding: 12px; background: #0ea5e9; border: none; color: white; font-weight: bold; border-radius: 6px; cursor: pointer; transition: background 0.2s; }
        button:hover { background: #0284c7; }
        .result { margin-top: 15px; text-align: center; }
        img { max-width: 100%; border-radius: 8px; margin-top: 10px; }
    </style>
</head>
<body>
    <div class="container">
        <h1>Meta Agent V1</h1>
        <div class="status">AGENT ACTIF</div>

        <div class="section">
            <label for="prompt">Générer une image (Pollinations)</label>
            <input type="text" id="prompt" placeholder="Ex: Futuristic cyberpunk city...">
            <button onclick="generateImage()">Générer l'image</button>
            <div class="result" id="imageResult"></div>
        </div>

        <div class="section">
            <label for="videoUrl">Télécharger une vidéo</label>
            <input type="text" id="videoUrl" placeholder="URL directe de la vidéo (.mp4)">
            <button onclick="downloadVideo()">Télécharger</button>
            <div class="result" id="videoResult"></div>
        </div>
    </div>

    <script>
        function generateImage() {
            const prompt = document.getElementById('prompt').value;
            if(!prompt) return alert('Entrez un prompt');
            const resDiv = document.getElementById('imageResult');
            resDiv.innerHTML = 'Génération en cours...';
            const imageUrl = `/api/generate?prompt=${encodeURIComponent(prompt)}`;
            resDiv.innerHTML = `<img src="${imageUrl}" alt="Generated Image">`;
        }

        function downloadVideo() {
            const url = document.getElementById('videoUrl').value;
            if(!url) return alert('Entrez une URL de vidéo');
            window.location.href = `/api/download?url=${encodeURIComponent(url)}`;
        }
    </script>
</body>
</html>
"""

@app.get("/", response_class=HTMLResponse)
def read_root():
    return HTML_CONTENT

@app.get("/api/generate")
def generate_image(prompt: str):
    image_url = f"https://image.pollinations.ai/prompt/{requests.utils.quote(prompt)}"
    try:
        resp = requests.get(image_url, timeout=30)
        if resp.status_code == 200:
            return Response(content=resp.content, media_type="image/jpeg")
        raise HTTPException(status_code=resp.status_code, detail="Erreur génération image")
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/download")
def download_video(url: str):
    try:
        req = requests.get(url, stream=True, timeout=60)
        if req.status_code == 200:
            return StreamingResponse(req.iter_content(chunk_size=8192), media_type=req.headers.get("content-type", "video/mp4"))
        raise HTTPException(status_code=req.status_code, detail="Impossible de télécharger la vidéo")
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

